"""0.3.1 regressions on an explicitly selected, disposable input-check-* project."""
import json,pathlib,subprocess,sys,time
root=pathlib.Path.cwd();sys.path.insert(0,str(root/'tools'))
from device_cdp import Device,ADB
d=Device();checks=[]
def check(name,expression,ok=bool):
    value=d.evaluate(expression);passed=ok(value);checks.append({'test':name,'passed':passed,'evidence':value});print(('PASS ' if passed else 'FAIL ')+name,flush=True);assert passed,str(value)[:800];return value
def touch(selector):
    p=d.evaluate('(()=>{const r=document.querySelector('+json.dumps(selector)+').getBoundingClientRect();return{x:(r.x+r.width/2)*devicePixelRatio,y:58+(r.y+r.height/2)*devicePixelRatio};})()')
    subprocess.run([ADB,'shell','input','tap',str(round(p['x'])),str(round(p['y']))],check=True);time.sleep(.12)
try:
    assert d.evaluate("forge.state.project.startsWith('input-check-')")
    d.evaluate("(async()=>{const name='input-check-031-'+Date.now();await native('newProject',{name,language:'cpp'});await forge.switchProject(name);await forge.openFile(forge.state.root+'/main.cpp');await forge.changeSettings({uiScale:100,codeScale:100});for(const x of document.querySelectorAll('dialog[open]'))x.close();})()")
    check('File/Code/View menus retain the visible native editor',r"(async()=>{const result=[];for(const kind of ['file','code','view']){forge.menu(forge.menuItems(kind),90,55);await NativeEditing.layout();result.push((await native('editorVisualState')).visible);}document.querySelector('#menu').classList.add('hidden');return result;})()",lambda v:all(v) and len(v)==3)
    d.evaluate("StudioChoices.open(document.querySelector('#standardSelect'))")
    check('Choices enter the browser top layer over other panels',"({top:StudioChoices.active.popover.matches(':popover-open'),modal:!!document.querySelector('dialog[open]')})",lambda v:v['top']and not v['modal'])
    touch('.studio-choice-popover [data-value="c++23"]')
    check('Android touch chooses a standard through the native editor cutout',"document.querySelector('#standardSelect').value==='c++23'&&!StudioChoices.active")
    check('One creation button opens anchored file/folder choices',"(()=>{forge.newFile();return{folder:!!document.querySelector('[data-create-kind=folder]'),cpp:!!document.querySelector('[data-create-kind=cpp]'),top:StudioPopover.current.element.matches(':popover-open'),modal:!!document.querySelector('dialog[open]'),oldFolderButton:!!document.querySelector('#newFolderButton')};})()",lambda v:v['folder']and v['cpp']and v['top']and not v['modal']and not v['oldFolderButton'])
    touch('[data-create-kind=folder]')
    check('Folder exists immediately with inline rename',r"(async()=>{for(let n=0;n<100&&!forge.treeRename;n++)await new Promise(r=>setTimeout(r,20));return{value:forge.treeRename?.input.value,modal:!!document.querySelector('dialog[open]'),found:JSON.stringify(await native('tree')).includes('new_folder')};})()",lambda v:v.get('value')=='new_folder'and v['found']and not v['modal'])
    check('Inline folder rename commits without asking for file type',r"(async()=>{forge.treeRename.input.value='src';await forge.treeRename.commit();return{selected:forge.treeSelection,editing:!!forge.treeRename};})()",lambda v:v['selected']['path'].endswith('/src')and not v['editing'])
    check('Creation follows the selected directory; only basename is selected',r"(async()=>{const item=await forge.createTreeItem('cpp',forge.treeDirectory());return{path:item.path,value:forge.treeRename.input.value,start:forge.treeRename.input.selectionStart,end:forge.treeRename.input.selectionEnd};})()",lambda v:v['path'].endswith('/src/new_file.cpp')and v['start']==0 and v['end']==8)
    check('Renaming preserves unsaved text, encoding and breakpoints',r"(async()=>{forge.active.model.setValue('// preserved rename\nint answer = 42;\n');await forge.debugger.toggleBreakpoint(forge.active.model,2);forge.treeRename.input.value='answer.cpp';await forge.treeRename.commit();const p=forge.state.root+'/src/answer.cpp';return{active:forge.active.path,text:(await native('read',{path:p})).text,points:forge.debugger.breakpoints.get(p)?.has(2)};})()",lambda v:v['active'].endswith('/src/answer.cpp')and'42'in v['text']and v['points'])
    check('Repeated creation chooses a free name without overwriting',r"(async()=>{const a=await native('createTreeItem',{kind:'hpp',directory:'src'}),b=await native('createTreeItem',{kind:'hpp',directory:'src'});return{a:a.path,b:b.path};})()",lambda v:v['a'].endswith('new_file.hpp')and v['b'].endswith('new_file2.hpp'))
    check('Conflict keeps the inline editor and both files',r"(async()=>{await forge.refreshTree();forge.renameTreeItem({path:forge.state.root+'/src/answer.cpp',dir:false});forge.treeRename.input.value='new_file.hpp';await forge.treeRename.commit();const invalid=forge.treeRename.input.getAttribute('aria-invalid');forge.treeRename.input.value='answer.cpp';await forge.treeRename.commit();return invalid==='true'&&(await native('read',{path:forge.state.root+'/src/answer.cpp'})).text.includes('42');})()")
    check('Project list includes an anchored Add project form',"(()=>{StudioChoices.open(document.querySelector('#projectSelect'));document.querySelector('.studio-project-add').click();const form=StudioPopover.current?.element;const result=!!form?.elements.projectName&&!document.querySelector('dialog[open]');StudioPopover.close();return result;})()")
    check('Bluetooth alternatives take priority over duplicate-line/navigation bindings',"(()=>{const original=forge.debugger,oldBuild=forge.debugBuild,calls=[];forge.debugger={active:true,action:a=>calls.push(a),breakpointAtCaret:()=>calls.push('breakpoint'),runToCursor:()=>calls.push('cursor')};forge.debugBuild=()=>calls.push('debug');try{for(const key of ['ArrowRight','ArrowDown','ArrowUp','b','r','d','t'])forge.keydown({key,ctrlKey:true,altKey:true,shiftKey:false,preventDefault(){},stopImmediatePropagation(){}});return calls;}finally{forge.debugger=original;forge.debugBuild=oldBuild;}})()",lambda v:v==['next','step','finish','breakpoint','continue','debug','cursor'])
    check('File tabs use content width instead of a large minimum',"[...document.querySelectorAll('.tab')].map(e=>({width:e.getBoundingClientRect().width,min:getComputedStyle(e).minWidth}))",lambda v:len(v)>0 and all(x['min']=='0px'for x in v))
    check('GCC removal preserves CMake and optional tools; offline restore works',r"(async()=>{await forge.saveAll();const before=await native('toolPacks');await forge.setToolPack('gcc',false);const removed=await native('toolPacks');const cmake=await native('probe');const clang=await native('build',{path:forge.state.root+'/main.cpp',mode:'file',options:{...forge.settings,compiler:'clang'},id:'clang-without-gcc'});await forge.setToolPack('gcc',true);const restored=await native('toolPacks');return{before:before.packs.map(p=>[p.id,p.installed]),removed:removed.packs.map(p=>[p.id,p.installed]),restored:restored.packs.map(p=>[p.id,p.installed]),cmake,clangCode:clang.code};})()",lambda v:dict(v['removed'])['gcc']==False and all(dict(v['removed'])[x]for x in ['analysis','clang','git','debugger'])and dict(v['restored'])['gcc']and v['clangCode']==0 and any('cmake version'in str(x).lower()for x in v['cmake'].values()))
finally:
    try:d.evaluate("StudioPopover.close();StudioChoices.close();document.querySelector('#menu').classList.add('hidden')")
    except Exception:pass
    d.close();(root/'verification-tablet-031.json').write_text(json.dumps({'device':'Xiaomi Pad 6 / Android 14','checks':checks,'passed':sum(x['passed']for x in checks),'total':len(checks)},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
